
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_b1wc_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_b1wc", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.672387037470475e+00, -3.602355149879281e+00, -3.504242043699959e+00, -3.368368284894804e+00, -3.183296483690094e+00, -2.937117771946979e+00, -2.620492002416661e+00, -2.232064272636154e+00, -1.785842207710701e+00, -1.318596111436409e+00, -8.899240086073561e-01, -6.285728532526436e-01, -5.512712759617339e-01, -4.502443344498939e-01, -3.197999363709731e-01, -1.980739831069958e-01, -1.100681583407298e-01, -4.139562926660234e-02, -9.076411945347701e-03, -1.021600742178413e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


